import{_ as t,o as s,c as o,ag as a}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Troubleshooting entity resolutions","description":"","frontmatter":{},"headers":[],"relativePath":"operations/troubleshooting-resolutions.md","filePath":"operations/troubleshooting-resolutions.md"}'),n={name:"operations/troubleshooting-resolutions.md"};function i(r,e,d,l,h,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="troubleshooting-entity-resolutions" tabindex="-1">Troubleshooting entity resolutions <a class="header-anchor" href="#troubleshooting-entity-resolutions" aria-label="Permalink to &quot;Troubleshooting entity resolutions&quot;">​</a></h1><h2 id="what-this-page-is-for" tabindex="-1">What this page is for <a class="header-anchor" href="#what-this-page-is-for" aria-label="Permalink to &quot;What this page is for&quot;">​</a></h2><p>When VERA&#39;s entity resolution does the wrong thing — picks the wrong project, ignores a pronoun, fails to auto-create a client — this is how an operator (or the affected user) finds out why.</p><p>The resolution pipeline is now live on every inbound DM. It runs before every Claude call, tokenises the user&#39;s message, identifies the intended action (verb), and resolves each referenced entity (project, client, person, task) against the database. Every message that matches a verb produces a <code>!debug last</code> record. The result is also logged to stdout so you can query it across time and users.</p><hr><h2 id="the-debug-last-command" tabindex="-1">The <code>!debug last</code> command <a class="header-anchor" href="#the-debug-last-command" aria-label="Permalink to &quot;The \`!debug last\` command&quot;">​</a></h2><p>DM VERA: <code>!debug last</code></p><p>VERA returns the most recent resolution it ran for your Slack user. The output looks like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Last resolution — 2026-05-16 22:14 UTC</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Message: &quot;create project Foo for Acme&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Extractor: matched verb create_project (typed as &quot;create&quot;)</span></span>
<span class="line"><span>  project_name: &quot;Foo&quot; (project)</span></span>
<span class="line"><span>  client_name:  &quot;Acme&quot; (client)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Resolver:</span></span>
<span class="line"><span>  project_name        → not_found</span></span>
<span class="line"><span>  client_name         → would_auto_create (proposed: &quot;Acme&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Missing slots: none</span></span></code></pre></div><p>Read the <code>Resolver:</code> section — it names every slot and its outcome. Each slot has one of these statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>resolved</code></td><td>Entity matched a single database row</td></tr><tr><td><code>ambiguous</code></td><td>Multiple rows matched — VERA needed to ask</td></tr><tr><td><code>not_found</code></td><td>No row matched</td></tr><tr><td><code>would_auto_create</code></td><td>No row, but the verb implies creating one alongside the main record</td></tr><tr><td><code>pronoun_resolved</code></td><td>A pronoun (<code>it</code>, <code>them</code>, etc.) matched a recent entity from this conversation</td></tr><tr><td><code>pronoun_unresolved</code></td><td>A pronoun had no plausible referent in conversation history</td></tr><tr><td><code>raw_passthrough</code></td><td>Non-entity value (hours, money, date) — carried through unchanged</td></tr><tr><td><code>mention_error</code></td><td>A Slack <code>@mention</code> couldn&#39;t be parsed</td></tr></tbody></table><p><strong><code>!debug last</code> is read-only.</strong> Calling it never produces a new resolution record.</p><p><strong>DM only.</strong> The command is ignored in channels — resolutions may contain entity names from other users&#39; conversations.</p><hr><h2 id="inline-debug-—-append-debug-last-to-any-dm" tabindex="-1">Inline debug — append <code>!debug last</code> to any DM <a class="header-anchor" href="#inline-debug-—-append-debug-last-to-any-dm" aria-label="Permalink to &quot;Inline debug — append \`!debug last\` to any DM&quot;">​</a></h2><p>Instead of sending <code>!debug last</code> as a separate follow-up, you can append the marker to any DM and VERA will return both the normal response and the resolution record in the same turn:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log 3 hours to CityCore on QA today !debug last</span></span></code></pre></div><p>VERA processes the action normally, then appends the resolution record separated by a <code>---</code> divider. The marker is stripped before the extractor and Claude see the message — they receive the clean text as if the marker were never there.</p><p><strong>Works with:</strong></p><ul><li>Any natural-language action (<code>create client Foo !debug last</code>)</li><li>Digit confirmations (<code>1 !debug last</code>)</li><li>The short alias <code>!debug</code> without <code>last</code> (<code>log 2h to Acme !debug</code>)</li></ul><p><strong>Does not trigger for:</strong></p><ul><li>Standalone <code>!debug last</code> — that still runs the existing standalone command</li><li>Mid-message occurrences (<code>show !debug last week&#39;s entries</code>) — the match requires end-of-string</li></ul><p>This is most useful during smoke testing: each step produces both the action result and the resolution in one message, halving the round-trips needed to verify entity resolution.</p><hr><h2 id="the-stdout-log" tabindex="-1">The stdout log <a class="header-anchor" href="#the-stdout-log" aria-label="Permalink to &quot;The stdout log&quot;">​</a></h2><p>Every resolution emits a single-line JSON object to stdout, captured by Railway. Use Railway&#39;s log search to query across users, tenants, and time ranges.</p><p><strong>Filter to a specific user:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>slack_user_id=&quot;U...&quot;</span></span></code></pre></div><p><strong>Find all not_found outcomes (entity the resolver couldn&#39;t match):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>event=&quot;resolution&quot; not_found</span></span></code></pre></div><p><strong>Find all pronoun fall-throughs:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pronoun_unresolved</span></span></code></pre></div><p><strong>Log line shape:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;resolution&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-05-16T22:14:33.012Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tenant_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;abc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slack_user_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;U123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message_ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1747...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;raw_message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;create project Foo for Acme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;extractor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;matched&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;canonical_verb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;create_project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;resolver&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;resolutions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;missing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>raw_message</code> is truncated to 500 characters in the log. The in-memory record (accessible via <code>!debug last</code>) retains the full text.</p><hr><h2 id="common-failure-modes" tabindex="-1">Common failure modes <a class="header-anchor" href="#common-failure-modes" aria-label="Permalink to &quot;Common failure modes&quot;">​</a></h2><p><strong>Wrong entity picked from conversation history (pronoun resolved to stale entity)</strong></p><p>Check that <code>entities</code> is populated on the prior turn&#39;s conversation record. The pronoun scanner reads <code>conversations.entities</code> — if the column is empty for the turn where the entity was introduced, the pronoun will fall through to <code>pronoun_unresolved</code>. Look for <code>extractTurnEntities</code> in <code>index.js</code> — it runs after every tool call response and populates that column.</p><p><strong>Pronoun came back unresolved even though the entity was mentioned recently</strong></p><p>The entity must have been the result of a tool call (e.g. <code>get_project_info</code> returned it) for it to land in <code>conversations.entities</code>. A message that only mentioned the entity by name in prose, without a tool call confirming it, won&#39;t populate the column.</p><p><strong>Client got auto-created when we wanted to use an existing one</strong></p><p>The resolver matched <code>would_auto_create</code> because the client name wasn&#39;t an exact or near-exact match to any existing client. Use the exact stored name, or check for a typo.</p><p><strong>Project resolved to the wrong one when names are similar</strong></p><p>The resolver found an <code>ambiguous</code> match but VERA still proceeded — this means the wiring layer chose one. Check <code>!debug last</code> to see the candidates list. If the intended project isn&#39;t in the candidates, the name diverges more than expected.</p><p><strong>Resolution looks wrong but <code>!debug last</code> shows no record</strong></p><p>Every inbound DM now produces a <code>!debug last</code> record — including confirmation replies (<code>yes</code>, <code>1</code>, etc.) and messages whose verb the extractor doesn&#39;t cover (e.g. <code>cancel</code>, <code>add user</code>). If <code>!debug last</code> returns nothing, the message handler likely short-circuited before the entity pipeline (e.g. a <code>!test</code> command, a dialing-menu digit, or a CSV export request). Check the structured stdout log for <code>event=&quot;resolution&quot;</code> entries.</p><p>For confirmation replies, the record shows <code>reason: confirmation_reply</code> and <code>pending_intent: &lt;verb&gt;</code> — telling you which tool was about to be called from the prior turn. For unmatched messages, the record shows <code>reason: no_verb_match</code> — confirming the extractor saw the text but found no known verb. If the verb is a common one that should be covered, consider adding it to <code>lib/verb-context-table.js</code>.</p><p>The legacy <code>[Pre-resolved: …]</code> annotation path (for non-wired user-bearing verbs) does not write to the ring buffer — check the outbound message for that prefix if <code>!debug last</code> shows only the extractor/resolver section without any tools.</p><hr><h2 id="what-this-page-does-not-cover" tabindex="-1">What this page does not cover <a class="header-anchor" href="#what-this-page-does-not-cover" aria-label="Permalink to &quot;What this page does not cover&quot;">​</a></h2><p>Issues outside the entity-resolution pipeline: LLM hallucinations, tool execution failures, permission errors. Those have their own paths — check the error reporter GitHub issues (labelled <code>auto-reported</code>) and the status dashboard at <code>/status</code>.</p>`,52)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
